#include "elevsim.h"
#include <stdlib.h>
#include <string.h>
#include <inttypes.h>
#include <errno.h>
#include <math.h>

static const char*outcome(const Passenger*p){return p->state==P_COMPLETED?"COMPLETED":"UNSERVED";}static double clean3(double x){return fabs(x)<0.0005?0:x;}static double clean6(double x){return fabs(x)<0.0000005?0:x;}static void f3(FILE*f,double x){fprintf(f,"%.3f",clean3(x));}static void f6(FILE*f,double x){fprintf(f,"%.6f",clean6(x));}static void jdist(FILE*f,bool a,double x,int d){if(!a)fputs("null",f);else if(d==6)f6(f,x);else f3(f,x);}static bool close_ok(FILE*f,EsError*e,const char*w){if(fclose(f)!=0){es_error(e,7,0,"failed closing %s",w);return false;}return true;}static FILE*op(const char*p,EsError*e){FILE*f=fopen(p,"wb");if(!f)es_error(e,7,0,"cannot open output %s: %s",p,strerror(errno));return f;}
bool reserve_targets(char**paths,size_t n,bool force,EsError*e){if(force)return true;size_t made=0;for(;made<n;made++){FILE*f=fopen(paths[made],"wbx");if(!f){es_error(e,7,0,"output target exists or cannot be reserved: %s",paths[made]);break;}if(fclose(f)!=0){es_error(e,7,0,"cannot close reserved output: %s",paths[made]);made++;break;}}if(made<n){for(size_t i=0;i<made;i++)remove(paths[i]);return false;}return true;}void cleanup_targets(char**p,size_t n){for(size_t i=0;i<n;i++)if(p[i])remove(p[i]);}
static bool manifest(const Config*c,const Trace*t,int alg,const char*pfx,const char*kind,const Metrics*m,EsError*e){char p[4096];snprintf(p,sizeof p,"%s.manifest.json",pfx);FILE*f=op(p,e);if(!f)return false;fputs("{\n  \"schema_version\": \"1.0\",\n  \"scenario_name\": ",f);es_json_write_string(f,c->name);fputs(",\n  \"run_kind\": ",f);es_json_write_string(f,kind);fputs(",\n  \"algorithm_id\": ",f);es_json_write_string(f,alg_ids((size_t)alg));fprintf(f,",\n  \"seed\": %" PRIu64 ",\n  \"trace_fingerprint\": \"%016" PRIx64 "\",\n  \"simulation_tick_ms\": %d,\n  \"configured_duration_s\": %d,\n  \"actual_elapsed_s\": %.3f,\n  \"end_mode\": \"%s\",\n  \"passenger_count\": %zu,\n  \"completed_count\": %zu,\n  \"unserved_count\": %zu,\n  \"status\": \"success\"\n}\n",c->seed,t->fingerprint,c->tick_ms,c->duration_s,clean3(m->elapsed_us/1e6),c->drain?"drain":"hard_stop",m->passengers,m->completed,m->unserved);return close_ok(f,e,"manifest");}
static void json_car(FILE*f,const Config*c,const Metrics*m,size_t i){const CarMetrics*x=&m->cars[i];fputs("    {\"id\": ",f);es_json_write_string(f,c->cars[i].id);fprintf(f,", \"utilization\": {\"moving_s\": %.3f, \"moving_pct\": %.3f, \"door_opening_s\": %.3f, \"door_opening_pct\": %.3f, \"door_open_s\": %.3f, \"door_open_pct\": %.3f, \"door_closing_s\": %.3f, \"door_closing_pct\": %.3f, \"idle_closed_s\": %.3f, \"idle_closed_pct\": %.3f}",x->moving_us/1e6,x->moving_pct,x->opening_us/1e6,x->opening_pct,x->open_us/1e6,x->open_pct,x->closing_us/1e6,x->closing_pct,x->idle_us/1e6,x->idle_pct);fprintf(f,", \"load\": {\"max_reserved_occupancy\": %u, \"mean_moving_onboard_load\": ",x->max_reserved);jdist(f,x->moving_load_avail,x->mean_moving_load,3);fputs(", \"mean_moving_load_ratio\": ",f);jdist(f,x->moving_load_avail,x->mean_moving_load_ratio,6);fprintf(f,", \"passenger_meter\": %.3f, \"full_capacity_ticks\": %" PRIu64 ", \"full_bypass_events\": %" PRIu64 "}",x->passenger_meter,x->full_ticks,x->full_bypass);fprintf(f,", \"movement\": {\"distance_m\": %.3f, \"floor_equivalent_distance\": %.3f, \"service_stops\": %" PRIu64 ", \"staging_arrivals\": %" PRIu64 ", \"door_cycles\": %" PRIu64 ", \"startups\": %" PRIu64 ", \"direction_reversals\": %" PRIu64 ", \"empty_distance_m\": %.3f, \"loaded_distance_m\": %.3f}",x->distance,x->floor_equiv,x->service_stops,x->staging_arrivals,x->door_cycles,x->startups,x->reversals,x->empty_distance,x->loaded_distance);fprintf(f,", \"energy\": {\"movement\": %.3f, \"startup\": %.3f, \"door\": %.3f, \"reverse\": %.3f, \"idle\": %.3f, \"load_meter\": %.3f, \"total\": %.3f}}",x->energy_move,x->energy_startup,x->energy_door,x->energy_reverse,x->energy_idle,x->energy_load,x->energy_total);}
static bool summary_json(const Config*c,int alg,const char*pfx,const Metrics*m,EsError*e){char p[4096];snprintf(p,sizeof p,"%s.summary.json",pfx);FILE*f=op(p,e);if(!f)return false;fprintf(f,"{\n  \"run\": {\"algorithm_id\": \"%s\", \"elapsed_s\": %.3f},\n",alg_ids((size_t)alg),clean3(m->elapsed_us/1e6));fprintf(f,"  \"passengers\": {\"trace_passengers\": %zu, \"arrived_passengers\": %zu, \"completed_passengers\": %zu, \"unserved_passengers\": %zu, \"passengers_bypassed_full\": %zu, \"full_capacity_bypass_events\": %" PRIu64 ", \"starvation_urgent_episodes\": %" PRIu64 "},\n",m->passengers,m->arrived,m->completed,m->unserved,m->bypassed_passengers,m->full_bypass,m->starvation_triggers);fputs("  \"waiting_time\": {\"mean_s\": ",f);jdist(f,m->wait_avail,m->mean_wait,3);fputs(", \"min_s\": ",f);jdist(f,m->wait_avail,m->min_wait,3);fputs(", \"max_s\": ",f);jdist(f,m->wait_avail,m->max_wait,3);fputs(", \"population_stddev_s\": ",f);jdist(f,m->wait_avail,m->std_wait,3);fputs(", \"p50_s\": ",f);jdist(f,m->wait_avail,m->p50_wait,3);fputs(", \"p90_s\": ",f);jdist(f,m->wait_avail,m->p90_wait,3);fputs(", \"p95_s\": ",f);jdist(f,m->wait_avail,m->p95_wait,3);fputs(", \"p99_s\": ",f);jdist(f,m->wait_avail,m->p99_wait,3);fputs("},\n",f);fputs("  \"ride_time\": {\"mean_s\": ",f);jdist(f,m->ride_avail,m->mean_ride,3);fputs(", \"min_s\": ",f);jdist(f,m->ride_avail,m->min_ride,3);fputs(", \"max_s\": ",f);jdist(f,m->ride_avail,m->max_ride,3);fputs(", \"p50_s\": ",f);jdist(f,m->ride_avail,m->p50_ride,3);fputs(", \"p95_s\": ",f);jdist(f,m->ride_avail,m->p95_ride,3);fputs(", \"p99_s\": ",f);jdist(f,m->ride_avail,m->p99_ride,3);fputs("},\n",f);fputs("  \"journey_time\": {\"mean_s\": ",f);jdist(f,m->journey_avail,m->mean_journey,3);fputs(", \"min_s\": ",f);jdist(f,m->journey_avail,m->min_journey,3);fputs(", \"max_s\": ",f);jdist(f,m->journey_avail,m->max_journey,3);fputs(", \"p50_s\": ",f);jdist(f,m->journey_avail,m->p50_journey,3);fputs(", \"p90_s\": ",f);jdist(f,m->journey_avail,m->p90_journey,3);fputs(", \"p95_s\": ",f);jdist(f,m->journey_avail,m->p95_journey,3);fputs(", \"p99_s\": ",f);jdist(f,m->journey_avail,m->p99_journey,3);fputs("},\n",f);fprintf(f,"  \"sla\": {\"completed_wait_violations\": %" PRIu64 ", \"all_arrived_wait_violations\": %" PRIu64 ", \"all_arrived_violation_pct\": %.3f, \"observed_wait_over_2x_sla\": %" PRIu64 "},\n",m->completed_sla_violations,m->sla_violations,m->sla_pct,m->over_2x_sla);fputs("  \"fairness\": {\"max_completed_wait_s\": ",f);jdist(f,m->wait_avail,m->max_wait,3);fputs(", \"p99_completed_wait_s\": ",f);jdist(f,m->wait_avail,m->p99_wait,3);fprintf(f,", \"observed_wait_over_2x_sla\": %" PRIu64 ", \"starvation_urgent_episodes\": %" PRIu64 ", \"max_hall_request_age_s\": %.3f, \"gini_wait\": ",m->over_2x_sla,m->starvation_triggers,m->max_hall_age);jdist(f,m->wait_avail,m->gini,6);fputs("},\n",f);fprintf(f,"  \"throughput\": {\"completed_per_hour\": %.3f},\n",m->throughput);fputs("  \"elevators\": [\n",f);for(size_t i=0;i<m->car_n;i++){json_car(f,c,m,i);fputs(i+1<m->car_n?",\n":"\n",f);}fputs("  ],\n",f);fprintf(f,"  \"movement\": {\"total_distance_m\": %.3f, \"floor_equivalent_distance\": %.3f, \"empty_distance_m\": %.3f, \"loaded_distance_m\": %.3f, \"passenger_meter\": %.3f, \"service_stops\": %" PRIu64 ", \"staging_arrivals\": %" PRIu64 ", \"startups\": %" PRIu64 ", \"door_cycles\": %" PRIu64 ", \"direction_reversals\": %" PRIu64 "},\n",m->total_distance,m->total_distance/c->floor_height,m->empty_distance,m->loaded_distance,m->passenger_meter,m->service_stops,m->staging_arrivals,m->startups,m->door_cycles,m->reversals);fprintf(f,"  \"energy\": {\"label\": \"simplified comparative score\", \"movement\": %.3f, \"startup\": %.3f, \"door\": %.3f, \"reverse\": %.3f, \"idle\": %.3f, \"load_meter\": %.3f, \"total\": %.3f}\n}\n",m->energy_move,m->energy_startup,m->energy_door,m->energy_reverse,m->energy_idle,m->energy_load,m->energy_total);return close_ok(f,e,"summary json");}
static void txt_dist(FILE*f,const char*n,bool a,double mean,double min,double max,double p50,double p90,double p95,double p99){fprintf(f,"%s: ",n);if(!a){fputs("N/A\n",f);return;}fprintf(f,"mean=%.3f min=%.3f max=%.3f p50=%.3f p90=%.3f p95=%.3f p99=%.3f\n",mean,min,max,p50,p90,p95,p99);}static void txt_ride(FILE*f,bool a,double mean,double min,double max,double p50,double p95,double p99){fputs("Ride Time: ",f);if(!a){fputs("N/A\n",f);return;}fprintf(f,"mean=%.3f min=%.3f max=%.3f p50=%.3f p95=%.3f p99=%.3f\n",mean,min,max,p50,p95,p99);}
static bool summary_txt(const Config*c,int alg,const char*pfx,const Metrics*m,EsError*e){char p[4096];snprintf(p,sizeof p,"%s.summary.txt",pfx);FILE*f=op(p,e);if(!f)return false;fprintf(f,"Scenario / Run\nScenario: %s\nElapsed (s): %.3f\n\nAlgorithm\n%s\n\nDemand / Completion\nTrace: %zu\nArrived: %zu\nCompleted: %zu\nUnserved: %zu\n\n",c->name,m->elapsed_us/1e6,alg_ids((size_t)alg),m->passengers,m->arrived,m->completed,m->unserved);txt_dist(f,"Waiting Time",m->wait_avail,m->mean_wait,m->min_wait,m->max_wait,m->p50_wait,m->p90_wait,m->p95_wait,m->p99_wait);txt_ride(f,m->ride_avail,m->mean_ride,m->min_ride,m->max_ride,m->p50_ride,m->p95_ride,m->p99_ride);txt_dist(f,"Journey Time",m->journey_avail,m->mean_journey,m->min_journey,m->max_journey,m->p50_journey,m->p90_journey,m->p95_journey,m->p99_journey);fprintf(f,"\nSLA / Fairness\nAll-arrived violations: %" PRIu64 " (%.3f%%)\nOver 2x SLA: %" PRIu64 "\nStarvation episodes: %" PRIu64 "\nMax hall age (s): %.3f\nGini: ",m->sla_violations,m->sla_pct,m->over_2x_sla,m->starvation_triggers,m->max_hall_age);if(m->wait_avail)fprintf(f,"%.6f\n",m->gini);else fputs("N/A\n",f);fputs("\nElevator Utilization\n",f);for(size_t i=0;i<m->car_n;i++){const CarMetrics*x=&m->cars[i];fprintf(f,"%s moving=%.3fs opening=%.3fs open=%.3fs closing=%.3fs idle=%.3fs\n",c->cars[i].id,x->moving_us/1e6,x->opening_us/1e6,x->open_us/1e6,x->closing_us/1e6,x->idle_us/1e6);}fprintf(f,"\nMovement / Load\nDistance: %.3f m\nEmpty: %.3f m\nLoaded: %.3f m\nPassenger-meter: %.3f\n\nSimplified Energy Score\nThis is a simplified comparative score, not electrical kWh.\nTotal: %.3f\n\nWarnings / Status\nWarnings: NONE\nStatus: SUCCESS\n",m->total_distance,m->empty_distance,m->loaded_distance,m->passenger_meter,m->energy_total);return close_ok(f,e,"summary txt");}
static bool passenger_csv(const Config*c,const Trace*t,const char*pfx,EsError*e){char p[4096];snprintf(p,sizeof p,"%s.passengers.csv",pfx);FILE*f=op(p,e);if(!f)return false;fputs("passenger_id,arrival_us,origin_floor,destination_floor,direction,assigned_elevator,boarding_start_us,fully_onboard_us,alighting_start_us,completion_us,waiting_s,ride_s,total_journey_s,final_wait_age_s,bypassed_full_count,outcome\n",f);for(size_t i=0;i<t->n;i++){const Passenger*x=&t->p[i];fprintf(f,"%" PRIu32 ",%" PRIu64 ",%d,%d,%s,",x->id,x->arrival_us,x->origin,x->dest,x->dir>0?"UP":"DOWN");if(x->has_board_start&&x->car>=0)es_csv_field(f,c->cars[x->car].id);fputc(',',f);if(x->has_board_start)fprintf(f,"%" PRIu64,x->board_start_us);fputc(',',f);if(x->has_onboard)fprintf(f,"%" PRIu64,x->onboard_us);fputc(',',f);if(x->has_alight)fprintf(f,"%" PRIu64,x->alight_start_us);fputc(',',f);if(x->has_complete)fprintf(f,"%" PRIu64,x->complete_us);fputc(',',f);if(x->has_onboard)f3(f,(x->onboard_us-x->arrival_us)/1e6);fputc(',',f);if(x->has_alight&&x->has_onboard)f3(f,(x->alight_start_us-x->onboard_us)/1e6);fputc(',',f);if(x->has_complete)f3(f,(x->complete_us-x->arrival_us)/1e6);fputc(',',f);if(x->state!=P_COMPLETED)f3(f,x->final_wait_age_us/1e6);fprintf(f,",%" PRIu32 ",%s\n",x->bypassed,outcome(x));}return close_ok(f,e,"passenger csv");}
static bool hist(const Config*c,const Trace*t,const char*pfx,EsError*e){char p[4096];snprintf(p,sizeof p,"%s.wait_histogram.txt",pfx);FILE*f=op(p,e);if(!f)return false;size_t completed=0;for(size_t i=0;i<t->n;i++)if(t->p[i].state==P_COMPLETED)completed++;for(int lo=0;lo<c->hist_max_s;lo+=c->hist_bucket_s){int up=lo+c->hist_bucket_s;if(up>c->hist_max_s)up=c->hist_max_s;size_t n=0;for(size_t i=0;i<t->n;i++)if(t->p[i].state==P_COMPLETED){double w=(t->p[i].onboard_us-t->p[i].arrival_us)/1e6;if(w>=lo&&w<up)n++;}fprintf(f,"[%d,%d) count=%zu pct=%.3f\n",lo,up,n,completed?100.0*n/completed:0);}size_t n=0;for(size_t i=0;i<t->n;i++)if(t->p[i].state==P_COMPLETED&&(t->p[i].onboard_us-t->p[i].arrival_us)/1e6>=c->hist_max_s)n++;fprintf(f,"[%d,+inf) count=%zu pct=%.3f\n",c->hist_max_s,n,completed?100.0*n/completed:0);return close_ok(f,e,"histogram");}
bool write_run_outputs(const Config*c,const Trace*t,int alg,const char*pfx,const char*kind,const Metrics*m,EsError*e){char p[4096];if(!manifest(c,t,alg,pfx,kind,m,e))return false;if(c->out_summary_json&&!summary_json(c,alg,pfx,m,e))return false;if(c->out_summary_txt&&!summary_txt(c,alg,pfx,m,e))return false;if(c->out_passenger&&!passenger_csv(c,t,pfx,e))return false;if(c->out_hist&&!hist(c,t,pfx,e))return false;if(!strcmp(kind,"compare_child"))return true;snprintf(p,sizeof p,"%s.trace.csv",pfx);if(!trace_write(t,p,e))return false;snprintf(p,sizeof p,"%s.trace_info.json",pfx);return trace_info_write(t,c,p,!strcmp(kind,"replay")?"trace":(c->traffic_generated?"generated":"trace"),e);}
static double r3(double x){return clean3(round(x*1000.0)/1000.0);}static void csv_opt3(FILE*f,bool a,double x){if(a)f3(f,x);}static void csv_opt6(FILE*f,bool a,double x){if(a)f6(f,x);}
static bool comparison_csv(const Config*c,const char*pfx,const Metrics*m,size_t n,EsError*e){char p[4096];snprintf(p,sizeof p,"%s.comparison.csv",pfx);FILE*f=op(p,e);if(!f)return false;fputs("algorithm_id,passengers,completed,unserved,mean_wait_s,p50_wait_s,p90_wait_s,p95_wait_s,p99_wait_s,max_wait_s,mean_journey_s,p95_journey_s,sla_violations,sla_violation_pct,starvation_triggers,gini_wait,throughput_per_hour,total_distance_m,empty_distance_m,door_cycles,direction_reversals,energy_score\n",f);for(size_t i=0;i<n;i++){const Metrics*x=&m[i];fprintf(f,"%s,%zu,%zu,%zu,",c->compare[i],x->passengers,x->completed,x->unserved);csv_opt3(f,x->wait_avail,x->mean_wait);fputc(',',f);csv_opt3(f,x->wait_avail,x->p50_wait);fputc(',',f);csv_opt3(f,x->wait_avail,x->p90_wait);fputc(',',f);csv_opt3(f,x->wait_avail,x->p95_wait);fputc(',',f);csv_opt3(f,x->wait_avail,x->p99_wait);fputc(',',f);csv_opt3(f,x->wait_avail,x->max_wait);fputc(',',f);csv_opt3(f,x->journey_avail,x->mean_journey);fputc(',',f);csv_opt3(f,x->journey_avail,x->p95_journey);fprintf(f,",%" PRIu64 ",%.3f,%" PRIu64 ",",x->sla_violations,clean3(x->sla_pct),x->starvation_triggers);csv_opt6(f,x->wait_avail,x->gini);fprintf(f,",%.3f,%.3f,%.3f,%" PRIu64 ",%" PRIu64 ",%.3f\n",clean3(x->throughput),clean3(x->total_distance),clean3(x->empty_distance),x->door_cycles,x->reversals,clean3(x->energy_total));}return close_ok(f,e,"comparison csv");}
typedef enum{CM_MEAN,CM_P95,CM_P99,CM_SLA,CM_MAX,CM_ENERGY,CM_THR} CmpMetric;
static bool cm_available(const Metrics*x,CmpMetric k){if(k==CM_MEAN||k==CM_P95||k==CM_P99||k==CM_MAX)return x->wait_avail;return true;}static double cm_value(const Metrics*x,CmpMetric k){switch(k){case CM_MEAN:return r3(x->mean_wait);case CM_P95:return r3(x->p95_wait);case CM_P99:return r3(x->p99_wait);case CM_SLA:return r3(x->sla_pct);case CM_MAX:return r3(x->max_wait);case CM_ENERGY:return r3(x->energy_total);case CM_THR:return r3(x->throughput);}return 0;}
static void winners(FILE*f,const Config*c,const Metrics*m,size_t n,const char*label,CmpMetric k){bool any=false;double best=0;for(size_t i=0;i<n;i++)if(cm_available(&m[i],k)){double v=cm_value(&m[i],k);if(!any||((k==CM_THR)?v>best:v<best)){best=v;any=true;}}fprintf(f,"%s: ",label);if(!any){fputs("N/A\n",f);return;}bool first=true;for(size_t i=0;i<n;i++)if(cm_available(&m[i],k)&&cm_value(&m[i],k)==best){if(!first)fputs(", ",f);fputs(c->compare[i],f);first=false;}fprintf(f," (%s=%.3f)\n",k==CM_THR?"highest":"lowest",best);}
static bool comparison_txt(const Config*c,const Trace*t,const char*pfx,const Metrics*m,size_t n,EsError*e){char p[4096];snprintf(p,sizeof p,"%s.comparison.txt",pfx);FILE*f=op(p,e);if(!f)return false;fprintf(f,"STATUS: SUCCESS\nTrace fingerprint: %016" PRIx64 "\nPassenger count: %zu\n\nAlgorithms\n",t->fingerprint,t->n);for(size_t i=0;i<n;i++){const Metrics*x=&m[i];fprintf(f,"%s completed=%zu unserved=%zu mean_wait=",c->compare[i],x->completed,x->unserved);if(x->wait_avail)fprintf(f,"%.3f",clean3(x->mean_wait));else fputs("N/A",f);fputs(" p95_wait=",f);if(x->wait_avail)fprintf(f,"%.3f",clean3(x->p95_wait));else fputs("N/A",f);fprintf(f," sla_pct=%.3f throughput=%.3f distance_m=%.3f energy=%.3f\n",clean3(x->sla_pct),clean3(x->throughput),clean3(x->total_distance),clean3(x->energy_total));}fputs("\nPer-metric winners (ties use canonical report rounding)\n",f);winners(f,c,m,n,"Mean wait",CM_MEAN);winners(f,c,m,n,"P95 wait",CM_P95);winners(f,c,m,n,"P99 wait",CM_P99);winners(f,c,m,n,"All-arrived SLA violation percentage",CM_SLA);winners(f,c,m,n,"Maximum completed wait",CM_MAX);winners(f,c,m,n,"Energy score",CM_ENERGY);winners(f,c,m,n,"Throughput",CM_THR);fputs("\nNo hidden universal composite score is implied; algorithms are compared by the reported metrics above.\n",f);return close_ok(f,e,"comparison txt");}
bool write_comparison(const Config*c,const Trace*t,const char*pfx,const Metrics*m,size_t n,EsError*e){if(c->out_comparison_csv&&!comparison_csv(c,pfx,m,n,e))return false;return comparison_txt(c,t,pfx,m,n,e);}
